  'Page and secure context': "Side og sikker kontekst", 'Display refresh': "Skærmopdatering", 'Pointer features': "Markørfunktioner", 'Input latency': "Inputforsinkelse", 'Encode speed': "Indkodningshastighed", 'Workers and offscreen canvas': "Workers og offscreen-lærred", 'Bitmaps and image decoding': "Bitmaps og billedafkodning", 'Storage': "Lager", 'WebGL 2 limits': "WebGL 2-grænser", 'Memory ramp': "Hukommelsesrampe",
